export function updateAccelIcon(element, suffix = "") {
  // Accelerometer
  if (
    document.getElementById(element.id + suffix + ":IconBackground") != null
  ) {
    // changes the color based on the state
    let color = "";
    let elementState;
    if(element.elementTypeState && element.elementTypeState.id) {
      elementState = getTrimId(element.elementTypeState.id);
    }

    if(typeof elementState != 'undefined') {
      if (elementState == 0) {
        color = "#ffcc00";
      } else if (elementState == 1) {
        color = "#008000";
      } else if (elementState == 2) {
        color = "#800080";
      } else if (elementState == 3) {
        color = "#ff0000";
      }

      document.getElementById(element.id + suffix + ":IconBackground").style[
        "fill"
      ] = color;
    }
  }
}
